.viz2-anatomy-q-boundary, .viz2-anatomy-slot-boundary, .viz2-anatomy-stack-boundary { fill: var(--surface-3); }
.viz2-anatomy-unused-page { fill: var(--surface-4); fill-opacity: .45; pointer-events: none; }
.viz2-anatomy-output-row { fill: var(--accent); }
.viz2-anatomy-link { fill: none; stroke: var(--foreground-muted); stroke-width: 1; opacity: .35; vector-effect: non-scaling-stroke; }
.viz2-anatomy-link.is-related { stroke: var(--primary); opacity: 1; }

#story {
  width:1600px;
