  display:grid;
  grid-template-rows:minmax(0,1fr) 38px;

.viz2-intra-reuse { fill:none; stroke:var(--slot-color); stroke-width:3; stroke-dasharray:4 4; stroke-linecap:round; opacity:.3; vector-effect:non-scaling-stroke; pointer-events:stroke; }
.viz2-intra-output { fill:var(--surface-2); stroke:var(--foreground-secondary); stroke-width:1; vector-effect:non-scaling-stroke; }
